bool ClangToSageTranslator::VisitNonTypeTemplateParmDecl(
    clang::NonTypeTemplateParmDecl *non_type_template_param_decl,
    SgNode **node) {
#if DEBUG_VISIT_DECL
  std::cerr << "ClangToSageTranslator::VisitNonTypeTemplateParmDecl"
            << std::endl;
#endif

  SgDeclarationStatement *owning_template = nullptr;
  if (clang::DeclContext *ctx =
          non_type_template_param_decl->getDeclContext()) {
    if (clang::TemplateDecl *template_ctx =
            llvm::dyn_cast<clang::TemplateDecl>(ctx)) {
      auto it = p_decl_translation_map.find(template_ctx);
      if (it != p_decl_translation_map.end()) {
        owning_template = isSgDeclarationStatement(it->second);
      }
    }
  }

  unsigned position = non_type_template_param_decl->getIndex();
  SgTemplateParameter *sg_param = translateTemplateParameter(
      non_type_template_param_decl, owning_template, position);

  *node = sg_param;
  return sg_param != nullptr;
}

bool ClangToSageTranslator::VisitVarDecl(clang::VarDecl *var_decl,
                                         SgNode **node) {
#if DEBUG_VISIT_DECL
  std::cerr << "ClangToSageTranslator::VisitVarDecl" << std::endl;
  std::cerr << "isStaticLocal " << var_decl->isStaticLocal() << std::endl;
  std::cerr << "isStaticDataMember " << var_decl->isStaticDataMember()
            << std::endl;
#endif
  // std::cerr << "DEBUG: VisitVarDecl for " << var_decl->getNameAsString() <<
  // std::endl;
  if (var_decl->getNameAsString() == "pack") {
    // std::cerr << "DEBUG: VisitVarDecl for pack. Type: " <<
    // var_decl->getType().getAsString() << std::endl;
  }
  bool res = true;

  if (clang::VarTemplateDecl *tmpl = var_decl->getDescribedVarTemplate()) {
    auto it_existing = p_decl_translation_map.find(var_decl);
    if (it_existing != p_decl_translation_map.end()) {
      *node = it_existing->second;
      return true;
    }
    auto it_template = p_decl_translation_map.find(tmpl);
    if (it_template != p_decl_translation_map.end()) {
      p_decl_translation_map[var_decl] = it_template->second;
      *node = it_template->second;
      return true;
    }
    if (p_decl_translation_in_progress.find(tmpl) ==
            p_decl_translation_in_progress.end() &&
        p_decl_translation_on_demand.find(tmpl) ==
            p_decl_translation_on_demand.end()) {
      if (SgNode *translated = TraverseOnDemand(tmpl)) {
        p_decl_translation_map[var_decl] = translated;
        *node = translated;
        return true;
      }
    }
  }

  // Create the SAGE node: SgVariableDeclaration

  SgName name(var_decl->getNameAsString());
  if (name.getString().empty() &&
      llvm::isa<clang::DecompositionDecl>(var_decl)) {
    SgScopeStatement *scope = SageBuilder::topScopeStack();
    ROSE_ASSERT(scope != nullptr);
    name = SgName(
        SageInterface::generateUniqueVariableName(scope, "structured_binding"));
  }

  clang::QualType varQualType = var_decl->getType();

  const clang::Type *varType = varQualType.getTypePtr();

#if DEBUG_VISIT_DECL
  // Wrap debug output in conditional to prevent production output
  if (name.getString() == "x") {
    // std::cerr << "DEBUG VarDecl: Variable 'x' has type class = " <<
    // varType->getTypeClassName() << std::endl;
  }
#endif

  // Pei-Hung (06/01/2022) check if the declaration is considered embedded in
  // Clang AST. If it is embedded, no explicit SgDeclaration should be placed
  // for ROSE AST.
  bool isembedded = false;
  bool iscompleteDefined = false;
  bool isDefinitionRequired = false;
  bool isNamedNonEmbeddedRecord = false;
  // Definitions embedded in a declarator are not autonomous.
  bool isAutonomousDeclaration = true;

  // Adding check for EaboratedType and PointerType to retrieve base EnumType
  // while((varType->getTypeClass() == clang::Type::Elaborated) ||
  // (varType->getTypeClass() == clang::Type::Pointer) ||
  // (varType->getTypeClass() == clang::Type::Array))
  clang::TagDecl *ownedTagDecl = nullptr;
  varQualType =
      stripQualifiedPointerArrayType(varQualType, nullptr, &ownedTagDecl);
  varType = varQualType.getTypePtr();

  auto is_inline_tag_definition = [&](clang::TagDecl *tag_decl) -> bool {
    if (tag_decl == nullptr || p_compiler_instance == nullptr) {
      return false;
    }
    clang::SourceRange decl_range = var_decl->getSourceRange();
    if (clang::TypeSourceInfo *tsi = var_decl->getTypeSourceInfo()) {
      clang::SourceRange type_range = tsi->getTypeLoc().getSourceRange();
      if (type_range.isValid()) {
        decl_range = type_range;
      }
    }
    if (!decl_range.isValid()) {
      return false;
    }
    return tagDefinitionWrittenInRange(tag_decl, decl_range,
                                       &p_compiler_instance->getSourceManager(),
                                       /*allow_fallback_loc_compare=*/false);
  };
  auto materialize_inline_tag_definition = [&](clang::TagDecl *tag_decl) {
    if (tag_decl == nullptr) {
      return;
    }
    p_inline_tag_decls.insert(tag_decl->getCanonicalDecl());
    (void)lookupSgDeclarationForClangDecl(tag_decl, /*allow_on_demand=*/true);
  };

  if (llvm::isa<clang::EnumType>(varType)) {
    clang::EnumType *underlyingEnumType = (clang::EnumType *)varType;
    clang::EnumDecl *enumDeclaration = underlyingEnumType->getDecl();
    if (clang::EnumDecl *writtenEnum =
            llvm::dyn_cast_or_null<clang::EnumDecl>(ownedTagDecl)) {
      if (is_inline_tag_definition(writtenEnum)) {
        enumDeclaration = writtenEnum;
      }
    }
    bool inline_tag_definition = is_inline_tag_definition(enumDeclaration);
    // For declarator-owned definitions, trust the written type range rather
    // than the tag's semantic context. In C, Clang can place a nested named
    // tag into translation-unit scope even when its definition is spelled
    // inline as part of the declarator.
    iscompleteDefined = enumDeclaration->isThisDeclarationADefinition() &&
                        inline_tag_definition;
    isembedded = iscompleteDefined;
    isAutonomousDeclaration = false;
    if (isembedded) {
      materialize_inline_tag_definition(enumDeclaration);
    }
  }

  if (llvm::isa<clang::RecordType>(varType)) {
    clang::RecordType *underlyingRecordType = (clang::RecordType *)varType;
    clang::RecordDecl *recordDeclaration = underlyingRecordType->getDecl();
    if (clang::RecordDecl *writtenRecord =
            llvm::dyn_cast_or_null<clang::RecordDecl>(ownedTagDecl)) {
      if (is_inline_tag_definition(writtenRecord)) {
        recordDeclaration = writtenRecord;
      }
    }
    const bool inline_tag_definition =
        is_inline_tag_definition(recordDeclaration);
    // For declarator-owned definitions, trust the written type range rather
    // than the tag's semantic context. In C, Clang can place a nested named
    // tag into translation-unit scope even when its definition is spelled
    // inline as part of the declarator.
    iscompleteDefined = recordDeclaration->isThisDeclarationADefinition() &&
                        inline_tag_definition;
    isembedded = iscompleteDefined;
    isAutonomousDeclaration = false;
    if (isembedded) {
      materialize_inline_tag_definition(recordDeclaration);
    }
    isNamedNonEmbeddedRecord = !isembedded &&
                               !recordDeclaration->isAnonymousStructOrUnion() &&
                               (recordDeclaration->getIdentifier() != nullptr ||
                                recordDeclaration->hasNameForLinkage());
  }

  // Only inline tag definitions owned by this declarator should be attached as
  // base-type defining declarations.
  isDefinitionRequired = iscompleteDefined;

  bool isStaticDataMember = var_decl->isStaticDataMember();
  bool isOutOfLineStaticMember = false;
  if (isStaticDataMember) {
    clang::DeclContext *lex_ctx = var_decl->getLexicalDeclContext();
    clang::DeclContext *sem_ctx = var_decl->getDeclContext();
    if (lex_ctx != nullptr && sem_ctx != nullptr && lex_ctx != sem_ctx) {
      isOutOfLineStaticMember = true;
    }
    if (var_decl->isOutOfLine()) {
      isOutOfLineStaticMember = true;
    }
  }

  const clang::DeclContext *var_type_decl_context =
      isOutOfLineStaticMember ? var_decl->getDeclContext() : nullptr;
  if (var_type_decl_context != nullptr) {
    ++p_preserve_current_class_qualifier_depth;
    p_template_parameter_decl_context_stack.push_back(var_type_decl_context);
  }

  SgType *sg_varType = buildTypeFromQualifiedType(varQualType);
  SgType *type = nullptr;
  if (clang::TypeSourceInfo *type_info = var_decl->getTypeSourceInfo()) {
    type = buildTypeFromTypeLoc(type_info->getTypeLoc());
  }
  if (type == nullptr) {
    type = buildTypeFromQualifiedType(var_decl->getType());
  }

  if (var_type_decl_context != nullptr) {
    ROSE_ASSERT(!p_template_parameter_decl_context_stack.empty());
    p_template_parameter_decl_context_stack.pop_back();
    ROSE_ASSERT(p_preserve_current_class_qualifier_depth > 0);
    --p_preserve_current_class_qualifier_depth;
  }

  bool implicit_anonymous_aggregate_var = false;
  if (var_decl->isImplicit() && name.getString().empty()) {
    const clang::RecordType *record_type =
        llvm::dyn_cast_or_null<clang::RecordType>(varType);
    const clang::RecordDecl *record_decl_for_var =
        record_type != nullptr ? record_type->getDecl() : nullptr;
    implicit_anonymous_aggregate_var =
        record_decl_for_var != nullptr &&
        record_decl_for_var->isAnonymousStructOrUnion();
  }
  if (implicit_anonymous_aggregate_var) {
    SgType *base_type = type != nullptr ? type->findBaseType() : nullptr;
    if (SgClassType *class_type = isSgClassType(base_type)) {
      auto mark_unnamed = [](SgClassDeclaration *decl) {
        if (decl != nullptr) {
          // Keep the synthesized internal name so symbol-table lookups for the
          // anonymous aggregate remain stable; isUnNamed controls user-visible
          // anonymity.
          decl->set_isUnNamed(true);
        }
      };
      if (SgClassDeclaration *decl =
              isSgClassDeclaration(class_type->get_declaration())) {
        mark_unnamed(decl);
        mark_unnamed(
            isSgClassDeclaration(decl->get_firstNondefiningDeclaration()));
        mark_unnamed(isSgClassDeclaration(decl->get_definingDeclaration()));
      }
    }
  }

  const clang::TemplateSpecializationKind var_specialization_kind =
      var_decl->getTemplateSpecializationKind();

  const bool emit_as_template_variable_declaration =
      isStaticDataMember && isOutOfLineStaticMember &&
      var_specialization_kind == clang::TSK_ExplicitSpecialization;
  auto build_var_declaration =
      [&](SgScopeStatement *decl_scope) -> SgVariableDeclaration * {
    if (emit_as_template_variable_declaration) {
      return SageBuilder::buildTemplateVariableDeclaration_nfi(
          name, type, nullptr, decl_scope);
    }
    return SageBuilder::buildVariableDeclaration_nfi(name, type, nullptr,
                                                     decl_scope);
  };
  auto resolve_static_member_scope = [&]() -> SgScopeStatement * {
    if (!isStaticDataMember || isOutOfLineStaticMember) {
      return nullptr;
    }
    clang::DeclContext *ctx = var_decl->getDeclContext();
    auto *record_ctx = llvm::dyn_cast_or_null<clang::RecordDecl>(ctx);
    if (record_ctx == nullptr) {
      return nullptr;
    }
    SgScopeStatement *resolved_scope =
        resolveScopeFromDeclContext(record_ctx, SageBuilder::topScopeStack());
    SgClassDefinition *class_def = isSgClassDefinition(resolved_scope);
    if (class_def == nullptr) {
      if (SgClassDeclaration *class_decl =
              isSgClassDeclaration(resolved_scope)) {
        class_def = class_decl->get_definition();
      }
    }
    if (class_def == nullptr && record_ctx->getDefinition() != nullptr) {
      if (SgNode *def_node = TraverseOnDemand(record_ctx->getDefinition())) {
        if (SgClassDeclaration *def_decl = isSgClassDeclaration(def_node)) {
          class_def = def_decl->get_definition();
        } else if (SgClassDefinition *def_def = isSgClassDefinition(def_node)) {
          class_def = def_def;
        }
      }
    }
    if (class_def != nullptr) {
      return class_def;
    }
    if (SgClassDefinition *enclosing =
            SageInterface::getEnclosingClassDefinition(
                SageBuilder::topScopeStack(), true)) {
      return enclosing;
    }
    return resolved_scope;
  };
  SgScopeStatement *static_member_scope = resolve_static_member_scope();

  //    SgVariableDeclaration * sg_var_decl = new SgVariableDeclaration(name,
  //    type, init); // scope: obtain from the scope stack.
  // Pei-Hung (09/01/2022) In test2022_3.c, the variable symbol needs to be
  // avaiable before processing the RHS. calling buildVariableDeclaration_nfi to
  // get the symbol in place.
  SgVariableDeclaration *sg_var_decl = nullptr;
  // Pei-Hung (09/29/23) The definition of a static data member needs to call
  // set_prev_decl_item to point to its first static data member declaration
  // inside the class. buildVariableDeclaration_nfi will take care of the
  // details by looking up the SgSymbol in the symbol table of the class.
  if (isStaticDataMember && var_decl->getPreviousDecl() != nullptr) {
    clang::VarDecl *prevDecl = var_decl->getPreviousDecl();
    SgVariableDeclaration *sgPrevDecl = nullptr;
    auto it_prev = p_decl_translation_map.find(prevDecl);
    if (it_prev != p_decl_translation_map.end()) {
      sgPrevDecl = isSgVariableDeclaration(it_prev->second);
    }
    if (sgPrevDecl == nullptr) {
      SgScopeStatement *saved_scope = SageBuilder::topScopeStack();
      SgScopeStatement *decl_scope_hint =
          resolveScopeFromDeclContext(prevDecl->getDeclContext(), saved_scope);
      if (decl_scope_hint != nullptr && decl_scope_hint != saved_scope) {
        SageBuilder::pushScopeStack(decl_scope_hint);
      }
      sgPrevDecl = isSgVariableDeclaration(Traverse(prevDecl));
      if (decl_scope_hint != nullptr && decl_scope_hint != saved_scope) {
        SageBuilder::popScopeStack();
      }
    }
    ROSE_ASSERT(sgPrevDecl);
    SgScopeStatement *decl_scope = nullptr;
    if (isOutOfLineStaticMember) {
      decl_scope = SageBuilder::topScopeStack();
    } else {
      decl_scope = SageInterface::getScope(sgPrevDecl);
      if (decl_scope == nullptr) {
        decl_scope = static_member_scope;
      }
    }
    if (decl_scope == nullptr) {
      decl_scope = SageBuilder::topScopeStack();
    }
    sg_var_decl = build_var_declaration(decl_scope);
    SgInitializedName *prev_init = sgPrevDecl->get_variables().empty()
                                       ? nullptr
                                       : sgPrevDecl->get_variables().front();
    SgInitializedName *current_init =
        sg_var_decl->get_variables().empty()
            ? nullptr
            : sg_var_decl->get_variables().front();
    if (prev_init != nullptr && current_init != nullptr) {
      current_init->set_prev_decl_item(prev_init);
    }
  } else {
    SgScopeStatement *decl_scope = SageBuilder::topScopeStack();
    if (!isStaticDataMember && var_decl->isFileVarDecl()) {
      if (clang::DeclContext *ctx = var_decl->getDeclContext()) {
        if (SgScopeStatement *resolved =
                resolveScopeFromDeclContext(ctx, decl_scope)) {
          decl_scope = resolved;
        }
      }
    }
    if (static_member_scope != nullptr) {
      decl_scope = static_member_scope;
    }
    sg_var_decl = build_var_declaration(decl_scope);
  }
  sg_var_decl->set_isAssociatedWithDeclarationList(true);
  if (var_decl->isConstexpr()) {
    sg_var_decl->set_is_constexpr(true);
  }

  if (var_specialization_kind == clang::TSK_ExplicitSpecialization) {
    sg_var_decl->set_specialization(SgDeclarationStatement::e_specialization);
  }

  // CLANG FRONTEND FIX: Check if variable has an initializer before traversing
  clang::Expr *init_expr = var_decl->getInit();
  SgExpression *expr = nullptr;
  SgExprListExp *expr_list_expr = nullptr;
  SgInitializer *init = nullptr;
  SgNode *tmp_init = nullptr;
  if (init_expr != nullptr) {
    tmp_init = Traverse(init_expr);
    expr = isSgExpression(tmp_init);
    if (tmp_init != nullptr && expr == nullptr) {
      if (SgInitializer *tmp_init_initializer = isSgInitializer(tmp_init)) {
        init = tmp_init_initializer;
      } else {
        std::cerr << "Runtime error: not a SgInitializer..."
                  << std::endl; // TODO
        res = false;
      }
    }
    if (expr != nullptr) {
      expr_list_expr = isSgExprListExp(expr);
      if (expr_list_expr != nullptr) {
        init = SageBuilder::buildAggregateInitializer(expr_list_expr, type);
      } else if (SgConstructorInitializer *ctor_init =
                     isSgConstructorInitializer(expr)) {
        if (var_decl->getInitStyle() == clang::VarDecl::CInit) {
          init = SageBuilder::buildAssignInitializer_nfi(ctor_init,
                                                         ctor_init->get_type());
        } else {
          init = ctor_init;
        }
      } else if (SgInitializer *existing_init = isSgInitializer(expr)) {
        init = existing_init;
      } else {
        init = SageBuilder::buildAssignInitializer_nfi(expr, expr->get_type());
      }
    }
  }

  // Pei-Hung (09/01/2022) setup initializer once the RHS is processed.
  // CLANG FRONTEND FIX: Only set initializer if it's not nullptr
  if (init != nullptr) {
    sg_var_decl->reset_initializer(init);
  }

  // CLANG FRONTEND FIX: Set initializer parent AFTER reset_initializer
  // reset_initializer sets the parent of the initializer to the
  // SgInitializedName, not the SgVariableDeclaration. Setting it to sg_var_decl
  // here was wrong. Only apply source range if we have both the initializer and
  // the original expression
  if (init != nullptr && init_expr != nullptr) {
    // Pei-Hung (07/12/2023):
    // applySourceRange should be set whenever the SgInitializer was just
    // created. Otherwise, it could overwrite the setting done in
    // setCompilerGeneratedFileInfo.
    if (!llvm::isa<clang::CXXConstructExpr>(init_expr)) {
      applySourceRange(init, init_expr->getSourceRange());
    }
  }

  // finding the bottom base type and check
  while (type->findBaseType() != type) {
    type = type->findBaseType();
    if (type == sg_varType)
      break;
  }

  if (isSgClassType(type) && isDefinitionRequired) {
    SgClassDeclaration *classDecl =
        isSgClassDeclaration(isSgClassType(type)->get_declaration());
    SgClassDeclaration *classDefDecl = isSgClassDeclaration(
        isSgClassType(type)->get_declaration()->get_definingDeclaration());
    if (isembedded && classDefDecl != nullptr &&
        !isSgDeclarationStatement(classDefDecl->get_parent())) {
      if (SgScopeStatement *parent_scope =
              isSgScopeStatement(classDefDecl->get_parent())) {
        detach_decl_from_scope_child_list(classDefDecl, parent_scope);
      }
      if (classDecl != nullptr && classDecl != classDefDecl) {
        if (SgScopeStatement *parent_scope =
                isSgScopeStatement(classDecl->get_parent())) {
          detach_decl_from_scope_child_list(classDecl, parent_scope);
        }
      }
      classDefDecl->set_parent(sg_var_decl);
      classDefDecl->set_isAutonomousDeclaration(isAutonomousDeclaration);
      sg_var_decl->set_baseTypeDefiningDeclaration(classDefDecl);
      sg_var_decl->set_variableDeclarationContainsBaseTypeDefiningDeclaration(
          true);
    }

    std::map<SgClassType *, bool>::iterator bool_it =
        p_class_type_decl_first_see_in_type.find(isSgClassType(type));
    ROSE_ASSERT(bool_it != p_class_type_decl_first_see_in_type.end());
    if (isNamedNonEmbeddedRecord) {
      // Named records that were defined through another declarator must keep
      // their semantic-scope definition instead of being re-embedded on first
      // variable use.
      bool_it->second = false;
    }
    if (bool_it->second) {
      sg_var_decl->set_baseTypeDefiningDeclaration(
          isSgNamedType(type)->get_declaration()->get_definingDeclaration());
      sg_var_decl->set_variableDeclarationContainsBaseTypeDefiningDeclaration(
          true);
      bool_it->second = false;
    }
  } else if (isSgEnumType(type) && isDefinitionRequired) {
    SgEnumDeclaration *enumDecl =
        isSgEnumDeclaration(isSgEnumType(type)->get_declaration());
    SgEnumDeclaration *enumDefDecl = isSgEnumDeclaration(
        isSgEnumType(type)->get_declaration()->get_definingDeclaration());
    if (isembedded && enumDefDecl != nullptr &&
        !isSgDeclarationStatement(enumDefDecl->get_parent())) {
      if (SgScopeStatement *parent_scope =
              isSgScopeStatement(enumDefDecl->get_parent())) {
        detach_decl_from_scope_child_list(enumDefDecl, parent_scope);
      }
      if (enumDecl != nullptr && enumDecl != enumDefDecl) {
        if (SgScopeStatement *parent_scope =
                isSgScopeStatement(enumDecl->get_parent())) {
          detach_decl_from_scope_child_list(enumDecl, parent_scope);
        }
      }
      enumDefDecl->set_parent(sg_var_decl);
      enumDefDecl->set_isAutonomousDeclaration(isAutonomousDeclaration);
      sg_var_decl->set_baseTypeDefiningDeclaration(enumDefDecl);
      sg_var_decl->set_variableDeclarationContainsBaseTypeDefiningDeclaration(
          true);
    }

    std::map<SgEnumType *, bool>::iterator bool_it =
        p_enum_type_decl_first_see_in_type.find(isSgEnumType(type));
    ROSE_ASSERT(bool_it != p_enum_type_decl_first_see_in_type.end());
    if (bool_it->second) {
      sg_var_decl->set_baseTypeDefiningDeclaration(
          isSgEnumType(type)->get_declaration()->get_definingDeclaration());
      sg_var_decl->set_variableDeclarationContainsBaseTypeDefiningDeclaration(
          true);
      bool_it->second = false;
    }
  }

  sg_var_decl->set_firstNondefiningDeclaration(sg_var_decl);
  SgScopeStatement *decl_parent = sg_var_decl->get_scope();
  if (decl_parent == nullptr) {
    decl_parent = SageBuilder::topScopeStack();
  }
  sg_var_decl->set_parent(decl_parent);

  // REX FIX: Handle AS_none for VarDecl to avoid unparser assertion
  clang::AccessSpecifier access = var_decl->getAccess();
  if (access == clang::AS_public) {
    sg_var_decl->get_declarationModifier().get_accessModifier().setPublic();
  } else if (access == clang::AS_private) {
    sg_var_decl->get_declarationModifier().get_accessModifier().setPrivate();
  } else if (access == clang::AS_protected) {
    sg_var_decl->get_declarationModifier().get_accessModifier().setProtected();
  } else if (access == clang::AS_none) {
    if (isSgClassDefinition(SageBuilder::topScopeStack())) {
      SgClassDefinition *class_def =
          isSgClassDefinition(SageBuilder::topScopeStack());
      if (class_def->get_declaration()->get_class_type() ==
          SgClassDeclaration::e_class) {
        sg_var_decl->get_declarationModifier()
            .get_accessModifier()
            .setPrivate();
      } else {
        sg_var_decl->get_declarationModifier().get_accessModifier().setPublic();
      }
    } else {
      sg_var_decl->get_declarationModifier().get_accessModifier().setPublic();
    }
  }

  ROSE_ASSERT(sg_var_decl->get_variables().size() == 1);

  SgInitializedName *init_name = sg_var_decl->get_variables()[0];
  ROSE_ASSERT(init_name != nullptr);
  if (isStaticDataMember && init_name->get_prev_decl_item() == nullptr) {
    clang::DeclContext *ctx = var_decl->getDeclContext();
    if (ctx != nullptr && llvm::isa<clang::RecordDecl>(ctx)) {
      // Ensure we link the out-of-line definition to the in-class declaration
      // so name qualification is preserved.
      auto find_member_init =
          [&](SgClassDefinition *class_def) -> SgInitializedName * {
        if (class_def == nullptr) {
          return nullptr;
        }
        const SgDeclarationStatementPtrList &members = class_def->get_members();
        for (SgDeclarationStatement *member : members) {
          if (SgVariableDeclaration *var_member =
                  isSgVariableDeclaration(member)) {
            for (SgInitializedName *member_init : var_member->get_variables()) {
              if (member_init != nullptr &&
                  member_init->get_name() == init_name->get_name()) {
                return member_init;
              }
            }
          }
        }
        return nullptr;
      };

      SgInitializedName *prev_init = nullptr;
      clang::VarDecl *first_decl = var_decl->getFirstDecl();
      if (first_decl != nullptr && first_decl != var_decl) {
        auto it_prev = p_decl_translation_map.find(first_decl);
        SgVariableDeclaration *prev_decl_node = nullptr;
        if (it_prev != p_decl_translation_map.end()) {
          prev_decl_node = isSgVariableDeclaration(it_prev->second);
        }
        if (prev_decl_node == nullptr) {
          SgScopeStatement *saved_scope = SageBuilder::topScopeStack();
          SgScopeStatement *decl_scope = resolveScopeFromDeclContext(
              first_decl->getDeclContext(), saved_scope);
          if (decl_scope != nullptr && decl_scope != saved_scope) {
            SageBuilder::pushScopeStack(decl_scope);
          }
          prev_decl_node = isSgVariableDeclaration(Traverse(first_decl));
          if (decl_scope != nullptr && decl_scope != saved_scope) {
            SageBuilder::popScopeStack();
          }
        }
        if (prev_decl_node != nullptr &&
            !prev_decl_node->get_variables().empty()) {
          prev_init = prev_decl_node->get_variables().front();
        }
      }

      if (prev_init == nullptr) {
        if (auto *parent_record =
                llvm::dyn_cast_or_null<clang::CXXRecordDecl>(ctx)) {
          SgScopeStatement *scope = resolveScopeFromDeclContext(
              parent_record, SageBuilder::topScopeStack());
          SgClassDefinition *class_def = isSgClassDefinition(scope);
          if (class_def == nullptr) {
            if (SgClassDeclaration *class_decl = isSgClassDeclaration(scope)) {
              class_def = class_decl->get_definition();
            }
          }
          if (class_def == nullptr &&
              parent_record->getDefinition() != nullptr) {
            if (SgNode *def_node =
                    TraverseOnDemand(parent_record->getDefinition())) {
              if (SgClassDeclaration *def_decl =
                      isSgClassDeclaration(def_node)) {
                class_def = def_decl->get_definition();
              } else if (SgClassDefinition *def_def =
                             isSgClassDefinition(def_node)) {
                class_def = def_def;
              }
            }
          }
          prev_init = find_member_init(class_def);
        }
      }

      if (prev_init != nullptr) {
        init_name->set_prev_decl_item(prev_init);
      }
    }
  }
  if (isStaticDataMember && isOutOfLineStaticMember) {
    clang::DeclContext *ctx = var_decl->getDeclContext();
    if (ctx != nullptr && llvm::isa<clang::RecordDecl>(ctx)) {
      SgScopeStatement *member_scope = nullptr;
      if (init_name->get_prev_decl_item() != nullptr) {
        member_scope = init_name->get_prev_decl_item()->get_scope();
      }
      if (member_scope == nullptr) {
        if (auto *record_ctx = llvm::dyn_cast_or_null<clang::RecordDecl>(
                var_decl->getDeclContext())) {
          SgScopeStatement *resolved_scope = resolveScopeFromDeclContext(
              record_ctx, SageBuilder::topScopeStack());
          SgClassDefinition *class_def = isSgClassDefinition(resolved_scope);
          if (class_def == nullptr) {
            if (SgClassDeclaration *class_decl =
                    isSgClassDeclaration(resolved_scope)) {
              class_def = class_decl->get_definition();
            }
          }
          if (class_def == nullptr && record_ctx->getDefinition() != nullptr) {
            if (SgNode *def_node =
                    TraverseOnDemand(record_ctx->getDefinition())) {
              if (SgClassDeclaration *def_decl =
                      isSgClassDeclaration(def_node)) {
                class_def = def_decl->get_definition();
              } else if (SgClassDefinition *def_def =
                             isSgClassDefinition(def_node)) {
                class_def = def_def;
              }
            }
          }
          if (class_def != nullptr) {
            member_scope = class_def;
          } else {
            member_scope = resolved_scope;
          }
        }
      }
      if (member_scope != nullptr) {
        SgScopeStatement *decl_scope = sg_var_decl->get_scope();
        if (decl_scope != nullptr && decl_scope != member_scope) {
          if (SgVariableSymbol *stale_sym =
                  decl_scope->lookup_variable_symbol(init_name->get_name())) {
            if (stale_sym->get_declaration() == init_name) {
              rehomeSymbolToScope(stale_sym, member_scope);
            }
          }
        }
        SgSymbol *existing_symbol = init_name->get_symbol_from_symbol_table();
        init_name->set_scope(member_scope);
        if (existing_symbol != nullptr) {
          rehomeSymbolToScope(existing_symbol, member_scope);
        }
        if (member_scope->find_symbol_from_declaration(init_name) == nullptr) {
          SgVariableSymbol *member_sym = new SgVariableSymbol(init_name);
          rehomeSymbolToScope(member_sym, member_scope);
        }
      } else {
        init_name->set_scope(SageBuilder::topScopeStack());
      }
    }
  } else if (init_name->get_scope() == nullptr) {
    init_name->set_scope(SageBuilder::topScopeStack());
  }
  if (!isStaticDataMember && var_decl->isFileVarDecl()) {
    SgScopeStatement *resolved_scope = nullptr;
    if (clang::DeclContext *ctx = var_decl->getDeclContext()) {
      resolved_scope =
          resolveScopeFromDeclContext(ctx, SageBuilder::topScopeStack());
    }
    if (resolved_scope == nullptr) {
      resolved_scope = SageBuilder::topScopeStack();
    }
    if (resolved_scope != nullptr &&
        isSgClassDefinition(init_name->get_scope()) != nullptr) {
      init_name->set_scope(resolved_scope);
    }
    if (var_decl->getPreviousDecl() == nullptr) {
      if (SgInitializedName *prev_init = init_name->get_prev_decl_item()) {
        SgScopeStatement *prev_scope = prev_init->get_scope();
        if (isSgClassDefinition(prev_scope) != nullptr) {
          init_name->set_prev_decl_item(nullptr);
        }
      }
    }
  }
  if (var_decl->getInitStyle() == clang::VarDecl::ListInit) {
    init_name->set_is_braced_initialized(true);
    if (!var_decl->isDirectInit()) {
      init_name->set_using_assignment_copy_constructor_syntax(true);
    }
  }
  if (var_decl->isConstexpr()) {
    bool explicit_const = true;
    if (const clang::TypeSourceInfo *type_info =
            var_decl->getTypeSourceInfo()) {
      explicit_const = type_info->getType().isLocalConstQualified();
    }
    init_name->set_is_constexpr_const_implicit(!explicit_const);
  }
  // CLANG FRONTEND FIX: Set initializer parent to SgInitializedName
  // The initializer is a child of the SgInitializedName, not the
  // SgVariableDeclaration
  if (init != nullptr) {
    init->set_parent(init_name);
  }

  applySourceRange(init_name, var_decl->getSourceRange());

  // CLANG FRONTEND FIX: The declptr should already be set by
  // SgVariableDeclaration constructor to point to the SgVariableDefinition. If
  // it's null, we need to check why.
  SgVariableDefinition *var_def =
      isSgVariableDefinition(init_name->get_declptr());
  if (var_def == nullptr) {
    // If declptr is null, try to get it from the variable declaration
    // buildVariableDeclaration_nfi should have created a definition
    var_def = sg_var_decl->get_definition();
    if (var_def != nullptr) {
      init_name->set_declptr(var_def);
    } else {
      // Debug: why is var_def null?
      printf("ERROR: Variable definition is null for variable: %s\n",
             init_name->get_name().str());
      printf("  sg_var_decl = %p\n", sg_var_decl);
      printf("  init_name = %p\n", init_name);
      printf("  init_name->get_declptr() = %p\n", init_name->get_declptr());
      fflush(stdout);
    }
  }
  ROSE_ASSERT(var_def != nullptr);
  applySourceRange(var_def, var_decl->getSourceRange());

  // Pei-Hung (06/16/22) added "extern" modifier
  bool hasExternalStorage = var_decl->hasExternalStorage();
  if (hasExternalStorage) {
    sg_var_decl->get_declarationModifier().get_storageModifier().setExtern();
  }

  // Pei-Hung (06/16/22) added "static" modifier
  bool shouldSetStatic = (var_decl->getStorageClass() == clang::SC_Static) &&
                         !isOutOfLineStaticMember;
  if (shouldSetStatic) {
    sg_var_decl->get_declarationModifier().get_storageModifier().setStatic();
  }
  // Pei-Hung (03/14/23) added "static" modifier for data member
  if (isStaticDataMember) {
    // Pei-Hung (09/29/23) Only set for the first static data member
    // declaration (the in-class declaration).
    if (var_decl->getPreviousDecl() == nullptr) {
      sg_var_decl->get_declarationModifier().get_storageModifier().setStatic();
    }
  }

  switch (var_decl->getTSCSpec()) {
  case clang::TSCS_unspecified:
    break;
  case clang::TSCS___thread:
    sg_var_decl->get_declarationModifier()
        .get_storageModifier()
        .set_thread_local_storage(true);
    break;
  case clang::TSCS_thread_local:
  case clang::TSCS__Thread_local:
    sg_var_decl->set_is_thread_local(true);
    break;
  }

  if (!isembedded) {
    sg_var_decl->set_variableDeclarationContainsBaseTypeDefiningDeclaration(
        false);
  }

  *node = sg_var_decl;

  bool visit_res = VisitDeclaratorDecl(var_decl, node) && res;
  if (visit_res && p_compiler_instance != nullptr) {
    clang::SourceManager &sm = p_compiler_instance->getSourceManager();
    clang::SourceLocation loc = var_decl->getLocation();
    auto preserve_implicit_anonymous_aggregate =
        [&](clang::VarDecl *candidate) -> bool {
      if (candidate == nullptr || !candidate->isImplicit()) {
        return false;
      }

      clang::SourceLocation candidate_loc = candidate->getLocation();
      if (candidate_loc.isMacroID()) {
        candidate_loc = sm.getSpellingLoc(candidate_loc);
      }
      if (!candidate_loc.isValid()) {
        return false;
      }
      if (!sm.isWrittenInMainFile(candidate_loc) ||
          sm.isInSystemHeader(candidate_loc) ||
          sm.isWrittenInBuiltinFile(candidate_loc)) {
        return false;
      }

      clang::QualType candidate_type = candidate->getType();
      const clang::Type *type_ptr = candidate_type.getTypePtrOrNull();
      while (type_ptr != nullptr &&
             (typeHasElaboratedSpelling(type_ptr) ||
              llvm::isa<clang::AttributedType>(type_ptr) ||
              llvm::isa<clang::SubstTemplateTypeParmType>(type_ptr))) {
        if (typeHasElaboratedSpelling(type_ptr)) {
          candidate_type = candidate_type.getCanonicalType();
        } else if (const clang::AttributedType *attributed =
                       llvm::dyn_cast<clang::AttributedType>(type_ptr)) {
          candidate_type = attributed->getModifiedType();
        } else {
          candidate_type =
              llvm::cast<clang::SubstTemplateTypeParmType>(type_ptr)
                  ->getReplacementType();
        }
        type_ptr = candidate_type.getTypePtrOrNull();
      }

      const clang::RecordType *record_type =
          llvm::dyn_cast_or_null<clang::RecordType>(type_ptr);
      if (record_type == nullptr) {
        return false;
      }

      const clang::RecordDecl *record_decl = record_type->getDecl();
      return record_decl != nullptr && record_decl->isAnonymousStructOrUnion();
    };

    bool suppress_var = var_decl->isImplicit();
    if (suppress_var && preserve_implicit_anonymous_aggregate(var_decl)) {
      suppress_var = false;
    }
    if (suppress_var && name.getString().empty()) {
      suppress_var = false;
    }

    // Keep implicit variables only when they model source-level range-for
    // declarations. Other implicit VarDecls are compiler artifacts and should
    // remain suppressed to avoid injecting ghost members/declarations.
    if (suppress_var && var_decl->isCXXForRangeDecl()) {
      suppress_var = false;
    }

    if (!suppress_var) {
      if (loc.isMacroID()) {
        // Macro-spelled declarations used in source-level macros (e.g. GNU
        // statement-expressions in main-file macros) should be preserved using
        // their expansion location. Falling back to spelling location here
        // would incorrectly suppress declarations that are lexically in the
        // main file but spelled in headers.
        clang::SourceLocation expansion_loc = sm.getExpansionLoc(loc);
        if (expansion_loc.isValid() && sm.isWrittenInMainFile(expansion_loc) &&
            !sm.isInSystemHeader(expansion_loc) &&
            !sm.isWrittenInBuiltinFile(expansion_loc)) {
          loc = expansion_loc;
        } else {
          loc = sm.getSpellingLoc(loc);
        }
      }
      if (!loc.isValid()) {
        suppress_var = true;
      } else {
        if (!sm.isWrittenInMainFile(loc)) {
          suppress_var = true;
        }
        if (sm.isInSystemHeader(loc) || sm.isWrittenInBuiltinFile(loc)) {
          suppress_var = true;
        }
      }
    }

    if (suppress_var) {
      mark_compiler_generated_and_suppress_unparse(sg_var_decl);
      if (SgVariableDefinition *var_def = sg_var_decl->get_definition()) {
        mark_compiler_generated_and_suppress_unparse(var_def);
      }
      for (SgInitializedName *init_name : sg_var_decl->get_variables()) {
        if (init_name != nullptr) {
          mark_compiler_generated_and_suppress_unparse(init_name);
        }
      }
    }

    auto is_instantiated_static_member_pattern = [&]() -> bool {
      if (!var_decl->isStaticDataMember()) {
        return false;
      }

      clang::RecordDecl *record_ctx =
          llvm::dyn_cast<clang::RecordDecl>(var_decl->getDeclContext());
      clang::ClassTemplateSpecializationDecl *parent_spec =
          llvm::dyn_cast_or_null<clang::ClassTemplateSpecializationDecl>(
              record_ctx);
      if (parent_spec == nullptr) {
        return false;
      }

      const bool member_is_instantiation =
          var_specialization_kind == clang::TSK_ImplicitInstantiation ||
          var_specialization_kind ==
              clang::TSK_ExplicitInstantiationDeclaration ||
          var_specialization_kind == clang::TSK_ExplicitInstantiationDefinition;
      const clang::TemplateSpecializationKind parent_tsk =
          parent_spec->getTemplateSpecializationKind();
      const bool parent_is_instantiation =
          parent_tsk == clang::TSK_ImplicitInstantiation ||
          parent_tsk == clang::TSK_ExplicitInstantiationDeclaration ||
          parent_tsk == clang::TSK_ExplicitInstantiationDefinition;
      if (!member_is_instantiation && !parent_is_instantiation) {
        return false;
      }

      if (member_is_instantiation) {
        return true;
      }

      clang::SourceLocation member_loc = var_decl->getLocation();
      if (member_loc.isMacroID()) {
        member_loc = sm.getSpellingLoc(member_loc);
      }
      if (!member_loc.isValid()) {
        return true;
      }

      clang::CXXRecordDecl *pattern =
          parent_spec->getTemplateInstantiationPattern();
      if (pattern == nullptr) {
        if (clang::ClassTemplateDecl *primary =
                parent_spec->getSpecializedTemplate()) {
          pattern = primary->getTemplatedDecl();
        }
      }
      if (pattern == nullptr) {
        return false;
      }

      return sourceRangeContainsLocation(pattern->getSourceRange(), member_loc,
                                         &sm, true);
    };

    if (!suppress_var && is_instantiated_static_member_pattern()) {
      suppress_var = true;
      mark_compiler_generated_and_suppress_unparse(sg_var_decl);
      if (SgVariableDefinition *var_def = sg_var_decl->get_definition()) {
        mark_compiler_generated_and_suppress_unparse(var_def);
      }
      for (SgInitializedName *init_name : sg_var_decl->get_variables()) {
        if (init_name != nullptr) {
          mark_compiler_generated_and_suppress_unparse(init_name);
        }
      }
    }
  }
  return visit_res;
}

bool ClangToSageTranslator::VisitDecompositionDecl(
    clang::DecompositionDecl *decomposition_decl, SgNode **node) {
#if DEBUG_VISIT_DECL
  std::cerr << "ClangToSageTranslator::VisitDecompositionDecl" << std::endl;
#endif
  bool res = true;

  bool visit_res = VisitVarDecl(decomposition_decl, node);

  std::vector<StructuredBindingComponent> components;
  for (clang::BindingDecl *binding_decl : decomposition_decl->bindings()) {
    StructuredBindingComponent component;
    component.binding_decl = binding_decl;

    if (binding_decl != nullptr) {
      SgVariableDeclaration *binding_var_decl =
          isSgVariableDeclaration(Traverse(binding_decl));
      ROSE_ASSERT(binding_var_decl != nullptr);
      ROSE_ASSERT(!binding_var_decl->get_variables().empty());

      if (!binding_decl->getNameAsString().empty()) {
        component.initialized_name = binding_var_decl->get_variables().front();
      }
    }

    components.push_back(component);
  }

  if (SgVariableDeclaration *sg_var_decl = isSgVariableDeclaration(*node)) {
    if (!sg_var_decl->get_variables().empty()) {
      SgInitializedName *init_name = sg_var_decl->get_variables().front();
      init_name->set_structured_binding_pattern(buildStructuredBindingPattern(
          decomposition_decl, components, init_name->get_scope()));
    }
  }

  return visit_res && res;
}

